decompress_inputs.run:
try:
    shell("""
        echo "🗜️ Decompressing FASTA and GTF next to originals"
        gunzip -c {input.fasta_gz} > {output.fasta}
        gunzip -c {input.gtf_gz}   > {output.gtf}
    """)
except Exception as e:
    update_step_status(EXP_ID, "processing", "failed")
    raise e

build_bowtie2_index.run:
try:
    shell("""
        source /etc/profile.d/modules.sh
        module load bowtie2
        mkdir -p {params.idx_dir}
        bowtie2-build {input.fasta} {params.idx_dir}/reference_index --threads {threads}
        touch {output.done}
    """)
except Exception as e:
    update_step_status(EXP_ID, "processing", "failed")
    raise e

prep_circtools.run:
try:
    shell("""
        bash /beegfs/homes/wjcmellon/circtools.cloud/app/scripts/prep_circtools.sh run_output/alignment {params.outdir}
    """)
    # CREATE THE OUTPUT FILE REQUIRED BY SNAKEMAKE
    open(output.done, "w").close()

    update_step_status(EXP_ID, "processing", "completed")
except Exception as e:
    update_step_status(EXP_ID, "processing", "failed")
    raise e

build_hisat2_index.run:
try:
    update_step_status(EXP_ID, "ciriquant", "running")

    shell("""
        source /etc/profile.d/modules.sh
        module load hisat2
        mkdir -p {params.index_dir}
        hisat2-build -p {threads} {input.fasta} {params.index_prefix}
        touch {output.done}
    """)

except Exception as e:
    update_step_status(EXP_ID, "ciriquant", "failed")
    raise e
